INSERT INTO product (name, price, image_url, description) VALUES ('Мултифункционален Multitool', 1290, 'https://picsum.photos/200', 'Мултифункционален алат изработен од нерѓосувачки челик во црна боја. Содржи клешти, нож, ножици, шрафцигери, отворач и други практични алатки. Склопената должина изнесува 11 cm.');
INSERT INTO product (name, price, image_url, description) VALUES ('Комплет за чистење автомобил', 990, 'https://picsum.photos/200', 'Комплет за детално чистење на автомобил со микрофибер крпи, четки и сунѓерчиња. Сите додатоци се спакувани во компактна црна торбичка за лесно складирање и транспорт.');
INSERT INTO product (name, price, image_url, description) VALUES ('Power Bank 20.000 mAh', 1490, 'https://picsum.photos/200', 'Power bank со капацитет од 20.000 mAh и црно куќиште. Опремен е со USB и USB-C приклучок и поддржува брзо полнење на мобилни телефони, слушалки и други USB уреди.');
INSERT INTO product (name, price, image_url, description) VALUES ('Rechargeable LED Flashlight', 790, 'https://picsum.photos/200', 'LED батериска ламба со црно метално куќиште и USB приклучок за полнење. Има пет режими на осветлување и водоотпорно куќиште за користење во различни услови.');
INSERT INTO product (name, price, image_url, description) VALUES ('Beard Grooming Set', 1190, 'https://picsum.photos/200', 'Комплет за нега на брада составен од четка, чешел, ножички и масло за брада. Додатоците се спакувани во црна декоративна кутија со компактен и практичен дизајн.');
INSERT INTO product (name, price, image_url, description) VALUES ('Електричен тример за брада', 1990, 'https://picsum.photos/200', 'Безжичен електричен тример со црно-сребрено куќиште и повеќе наставци за различни должини на потстрижување. Се полни преку USB кабел и содржи четка за чистење.');
INSERT INTO product (name, price, image_url, description) VALUES ('Wireless Gaming Headset', 2490, 'https://picsum.photos/200', 'Безжични over-ear gaming слушалки со црно куќиште, меки перничиња и вграден микрофон. Bluetooth поврзувањето овозможува користење без кабел, додека батеријата обезбедува до 20 часа користење.');
INSERT INTO product (name, price, image_url, description) VALUES ('Кожен класичен паричник', 1490, 'https://picsum.photos/200', 'Класичен и компактен паричник направен од вистинска кожа, има кафеава боја и совршена текстура.');
INSERT INTO product (name, price, image_url, description) VALUES ('Магнетен држач за телефон за автомобил', 590, 'https://picsum.photos/200', 'Магнетен држач за телефон со црно алуминиумско куќиште и силен магнет. Се поставува на вентилациониот отвор во автомобилот и овозможува стабилно држење на телефонот.');
INSERT INTO product (name, price, image_url, description) VALUES ('Smart Bluetooth Key Finder', 890, 'https://picsum.photos/200', 'Bluetooth tracker со компактно црно куќиште со дијаметар од 36 mm. Се поврзува со мобилен телефон и овозможува пронаоѓање на прикачени предмети преку мобилна апликација.');
INSERT INTO product (name, price, image_url, description) VALUES ('BBQ Grill Tool Set', 1490, 'https://picsum.photos/200', 'Сет од три алатки за скара изработени од нерѓосувачки челик со црни рачки. Комплетот содржи клешти, шпатула и виљушка и доаѓа во црна торбичка за складирање.');
INSERT INTO product (name, price, image_url, description) VALUES ('Термос шише 500 ml', 890, 'https://picsum.photos/200', 'Термос шише со капацитет од 500 ml, изработено од нерѓосувачки челик со мат црна завршница. Двојниот изолиран ѕид ја одржува температурата на пијалакот, а капачето обезбедува непропустливо затворање.');
INSERT INTO product (name, price, image_url, description) VALUES ('Whiskey Glass Gift Set', 1290, 'https://picsum.photos/200', 'Подарочен сет со две стаклени чаши за виски и четири коцки за ладење изработени од природен камен. Сетот е спакуван во елегантна црна подарочна кутија.');
INSERT INTO product (name, price, image_url, description) VALUES ('Метален модел на спортски автомобил', 1490, 'https://picsum.photos/200', 'Детален метален модел на спортски автомобил во размер 1:24. Моделот има метална каросерија, гумени тркала, детална внатрешност и отворачки врати.');
INSERT INTO product (name, price, image_url, description) VALUES ('LEGO Technic автомобил', 1990, 'https://picsum.photos/200', 'Комплет за составување спортски автомобил со детална конструкција и подвижни механички делови. Сетот содржи 300 елементи и е наменет за љубители на автомобили и моделирање.');
INSERT INTO product (name, price, image_url, description) VALUES ('Gym Grip & Lifting Set', 890, 'https://picsum.photos/200', 'Фитнес сет со црни lifting straps и рачни grip тренери. Текстилните straps имаат засилени шевови, а grip тренерите се изработени од цврста пластика со гумени рачки.');
INSERT INTO product (name, price, image_url, description) VALUES ('Fishing Tackle Set', 990, 'https://picsum.photos/200', 'Комплет за риболов спакуван во компактна пластична кутија со прегради. Содржи риболовни мамки, куки, вртливки и други основни додатоци за риболов.');
INSERT INTO product (name, price, image_url, description) VALUES ('Outdoor Survival Kit', 1490, 'https://picsum.photos/200', 'Survival сет со основни алатки за активности на отворено, спакувани во црна водоотпорна футрола. Комплетот содржи мултифункционална алатка, компас, свирче и огнивце.');
INSERT INTO product (name, price, image_url, description) VALUES ('Precision Screwdriver Set', 990, 'https://picsum.photos/200', 'Комплет за прецизно одвртување со метална рачка и 24 различни битови. Сите делови се организирани во компактна црна кутија со магнетен држач за битовите.');
INSERT INTO product (name, price, image_url, description) VALUES ('Машки механички часовник', 2490, 'https://picsum.photos/200', 'Механички машки часовник со црн циферблат, сребрени ознаки и црно кожно ремче. Куќиштето има дијаметар од 42 mm, а часовникот има класичен аналоген приказ.');